import {readFileSync} from "node:fs";
const APP_VERSION=JSON.parse(readFileSync("package.json","utf8")).version;
import {expect,test,type Page} from "@playwright/test";
import {mock} from "./helpers/v1-ipc";
async function openImage(page:Page,chooseRectangle=true){await mock(page);await page.goto("/?editor");const png=await page.evaluate(()=>{const c=document.createElement("canvas");c.width=400;c.height=240;const x=c.getContext("2d")!;x.fillStyle="#e9effb";x.fillRect(0,0,400,240);x.fillStyle="#147efb";x.fillRect(40,40,160,100);x.fillStyle="#20242a";x.font="24px sans-serif";x.fillText("FerShot X 1.0",30,190);return c.toDataURL("image/png").split(",")[1];});await page.locator('input[type="file"]').setInputFiles({name:"Release.png",mimeType:"image/png",buffer:Buffer.from(png,"base64")});await expect(page.getByRole("button",{name:"select tool",exact:true})).toHaveAttribute("aria-pressed","true");if(chooseRectangle)await page.getByRole("button",{name:"rectangle tool",exact:true}).click();}
async function drag(page:Page,testid:string){const b=(await page.getByTestId(testid).boundingBox())!;await page.mouse.move(b.x+b.width*.2,b.y+b.height*.2);await page.mouse.down();await page.mouse.move(b.x+b.width*.7,b.y+b.height*.7);await page.mouse.up();}
async function calls(page:Page,command:string){return page.evaluate(command=>(window as any).__CALLS__.filter((c:any)=>c.command===command),command);}
test("one top toolbar contains all drawing/output tools and the image area has no controls",async({page})=>{await openImage(page);for(const name of ["rectangle tool","arrow tool","pen tool","ellipse tool","text tool","counter tool","blur tool","Copy image","Save image…","Upload ⌘S"]){await expect(page.getByRole("button",{name,exact:true})).toBeVisible();}await expect(page.getByRole("button",{name:/Compose images|Create composed image|Open image|Pin image/i})).toHaveCount(0);await expect(page.getByText("External FerShot links",{exact:true})).toHaveCount(0);await expect(page.getByRole("button",{name:/Automatic tonal|Measure|Annotate image/})).toHaveCount(0);await expect(page.locator(".stage").getByRole("button")).toHaveCount(0);const icons=await page.locator(".editor-unified-bar svg").evaluateAll(nodes=>nodes.map(n=>({width:getComputedStyle(n).width,stroke:getComputedStyle(n).strokeWidth})));expect(icons.every(i=>i.width==="16px"&&i.stroke==="1.75px")).toBe(true);await expect(page.getByRole("button",{name:"rectangle tool",exact:true})).toHaveCSS("background-color","rgb(15, 18, 22)");await expect(page.getByRole("button",{name:"rectangle tool",exact:true})).toHaveCSS("filter","none");await page.screenshot({path:"artifacts/qa/C70-editor-unified.png"});});
test("crop and resize are drafts until Enter, and Escape never commits",async({page})=>{await openImage(page);await page.getByRole("button",{name:"Image size",exact:true}).click();await page.getByRole("button",{name:"Crop Region",exact:true}).click();await drag(page,"direct-transform-stage");expect(await calls(page,"process_image")).toHaveLength(0);await page.keyboard.press("Enter");await expect.poll(()=>calls(page,"process_image")).toHaveLength(1);expect((await calls(page,"process_image"))[0].args.request.crop).toEqual({x:80,y:48,width:200,height:120});await page.getByRole("button",{name:"Return to source image",exact:true}).click();await page.getByRole("button",{name:"Image size",exact:true}).click();await page.getByRole("button",{name:"Crop Region",exact:true}).click();await drag(page,"direct-transform-stage");await page.keyboard.press("Escape");expect(await calls(page,"process_image")).toHaveLength(1);await page.getByRole("button",{name:"Image size",exact:true}).click();await page.getByRole("button",{name:"50%",exact:true}).click();expect(await calls(page,"process_image")).toHaveLength(1);await page.getByRole("button",{name:"Resize",exact:true}).click();await expect.poll(()=>calls(page,"process_image")).toHaveLength(2);expect((await calls(page,"process_image"))[1].args.request.resize).toEqual({width:200,height:120});});
test("blur creates a draggable draft element without applying a destructive image effect",async({page})=>{await openImage(page);await page.getByRole("button",{name:"blur tool",exact:true}).click();await drag(page,"advanced-workbench-stage");await expect(page.getByLabel("Advanced item count")).toHaveText("1 items");expect(await calls(page,"apply_image_effect")).toHaveLength(0);await expect(page.getByRole("button",{name:"blur tool",exact:true})).toHaveAttribute("aria-pressed","true");await expect.poll(async()=>{const rows=await calls(page,"local_cache_save_draft");return rows.at(-1)?.args.request.draft.advanced[0]?.annotation.tool;}).toBe("blur");});
test("unified rectangle/arrow/pen history remains editable and undoable",async({page})=>{await openImage(page);await page.getByRole("button",{name:"rectangle tool",exact:true}).click();const stage=page.locator(".fershot-advanced-workbench__stage");const b=(await stage.boundingBox())!;await page.mouse.move(b.x+30,b.y+30);await page.mouse.down();await page.mouse.move(b.x+140,b.y+100);await page.mouse.up();await expect(page.getByLabel("Advanced item count")).toHaveText("1 items");await page.getByRole("button",{name:"Undo",exact:true}).click();await expect(page.getByLabel("Advanced item count")).toHaveText("0 items");await page.getByRole("button",{name:"Redo",exact:true}).click();await expect(page.getByLabel("Advanced item count")).toHaveText("1 items");});
test("Library defaults to FTP at 25%, shows relative links and caches lazy thumbnails between tabs",async({page})=>{await mock(page);await page.goto("/");await expect(page.getByRole("tab",{name:/FTP/})).toHaveAttribute("data-state","active");expect(await page.locator(".library-sidebar").evaluate(el=>el.getBoundingClientRect().width/innerWidth)).toBeCloseTo(.25,2);await expect(page.getByRole("option",{name:/frozen.png/})).toBeVisible();await expect(page.locator(".library-thumbnail img")).toHaveCount(1);await expect(page.getByRole("option",{name:/frozen.png/})).toHaveAttribute("aria-selected","true");await expect(page.getByRole("img",{name:"Shared.png",exact:true})).toBeVisible();await page.getByRole("tab",{name:/Local/}).click();await expect(page.locator(".library-thumbnail img")).toHaveCount(2);const before=(await calls(page,"library_thumbnail")).length;await page.getByRole("tab",{name:/FTP/}).click();await expect(page.locator(".library-thumbnail img")).toHaveCount(1);expect((await calls(page,"library_thumbnail")).length).toBe(before);await page.getByRole("option",{name:/frozen.png/}).click();await expect(page.getByRole("img",{name:"Shared.png",exact:true})).toBeVisible();expect(await calls(page,"library_image")).toHaveLength(3);await page.screenshot({path:"artifacts/qa/C70-library-ftp.png"});});
test("remote deletion requires confirmation; cancellation and failures preserve history",async({page})=>{await mock(page);await page.goto("/");await page.getByRole("option",{name:/frozen.png/}).click();await page.getByRole("button",{name:"Delete from FTP",exact:true}).click();await expect(page.getByRole("alertdialog")).toBeVisible();await page.getByRole("button",{name:"Cancel",exact:true}).click();expect(await calls(page,"ftp_delete_remote")).toHaveLength(0);await page.getByRole("button",{name:"Delete from FTP",exact:true}).click();await page.evaluate(()=>(window as any).__FAIL_DELETE__=true);await page.getByRole("button",{name:"Delete permanently",exact:true}).click();await expect(page.getByRole("alert").filter({hasText:"Synthetic delete failure"})).toContainText("Synthetic delete failure");await expect(page.getByRole("option")).toHaveCount(1);await page.evaluate(()=>(window as any).__FAIL_DELETE__=false);await page.getByRole("button",{name:"Delete from FTP",exact:true}).click();await page.getByRole("button",{name:"Delete permanently",exact:true}).click();await expect(page.getByRole("option")).toHaveCount(0);expect((await calls(page,"ftp_delete_remote"))[0].args).toEqual({id:"123-1",confirmed:true});});
test("scroll capture uses the native region/autoscroll entry and closing the last image hides Edit",async({page})=>{await mock(page);await page.goto("/?editor");await expect.poll(()=>page.evaluate(()=>(window as any).__CALLS__.some((c:any)=>c.command==="plugin:event|listen"&&c.args.event==="fershot-menu-action"))).toBe(true);await page.evaluate(()=>(window as any).__EMIT__("fershot-menu-action","capture-scrolling"));await expect.poll(()=>calls(page,"capture_scroll_image")).toHaveLength(1);await expect(page.getByRole("button",{name:"rectangle tool",exact:true})).toBeVisible();await page.evaluate(()=>(window as any).__EMIT__("fershot-editor-closed"));await expect(page.getByTestId("advanced-workbench-stage")).toHaveCount(0);});

test("Konva commits vectors once per gesture and Local retains one editable draft through crop and reopen",async({page})=>{
 await openImage(page);await expect(page.locator('[data-engine="react-konva"]')).toHaveCount(1);await expect(page.getByRole("searchbox")).toHaveCount(0);
 const stage=page.getByTestId("advanced-workbench-stage"),bounds=(await stage.boundingBox())!;
 await page.mouse.move(bounds.x+30,bounds.y+30);await page.mouse.down();await page.mouse.move(bounds.x+130,bounds.y+100);
 await expect(page.getByLabel("Advanced item count")).toHaveText("0 items");await page.mouse.up();await expect(page.getByLabel("Advanced item count")).toHaveText("1 items");
 await expect.poll(async()=>{const rows=await calls(page,"local_cache_save_draft");return rows.some((r:any)=>r.args.request.draft.advanced.length===1&&r.args.request.pngBase64===null);}).toBe(true);
 const saved=(await calls(page,"local_cache_save_draft")).at(-1).args.request,id=saved.id;expect(saved.draft.advanced[0].annotation.tool).toBe("rectangle");
 await page.getByRole("button",{name:"Image size",exact:true}).click();await page.getByRole("button",{name:"Crop Region",exact:true}).click();await drag(page,"direct-transform-stage");await page.keyboard.press("Enter");
 await expect.poll(async()=>new Set((await calls(page,"local_cache_save_draft")).map((r:any)=>r.args.request.id)).size).toBe(1);
 await expect.poll(async()=>{const rows=await calls(page,"local_cache_save_draft");return rows.at(-1).args.request.draft.width;}).toBe(200);
 expect((await calls(page,"local_cache_save_draft")).at(-1).args.request.draft.advanced).toHaveLength(1);
 await page.evaluate(()=>(window as any).__EMIT__("fershot-editor-closed"));await expect.poll(async()=>page.evaluate(()=>Object.keys((window as any).__DRAFTS__).length)).toBe(1);await page.waitForTimeout(450);expect(await page.evaluate(id=>(window as any).__DRAFTS__[id].draft.width,id)).toBe(200);
 await page.evaluate(id=>{const host=window as any;host.__INBOX__.push({...host.__DRAFTS__[id],localId:id});host.__EMIT__("fershot-editor-image");},id);
 await expect(page.getByLabel("Advanced item count")).toHaveText("1 items");await page.getByRole("button",{name:"select tool",exact:true}).click();
 await expect(page.locator('[data-engine="react-konva"] canvas')).not.toHaveCount(0);
});

test("Konva selection moves editable elements and preserves them in copied output draft",async({page})=>{await openImage(page);const stage=page.getByTestId("advanced-workbench-stage"),b=(await stage.boundingBox())!;await page.mouse.move(b.x+30,b.y+30);await page.mouse.down();await page.mouse.move(b.x+130,b.y+100);await page.mouse.up();await page.getByRole("button",{name:"select tool",exact:true}).click();await page.mouse.move(b.x+30,b.y+60);await page.mouse.down();await page.mouse.move(b.x+50,b.y+80);await page.mouse.up();await expect.poll(async()=>{const rows=await calls(page,"local_cache_save_draft"),last=rows.at(-1)?.args.request.draft.advanced[0];return last?.annotation.points[0].x;}).toBe(50);await page.getByRole("button",{name:"Copy image",exact:true}).click();await expect.poll(()=>calls(page,"copy_image")).toHaveLength(1);const draft=(await calls(page,"local_cache_save_draft")).at(-1).args.request.draft;expect(draft.advanced).toHaveLength(1);expect(draft.advanced[0].annotation.points[0]).toEqual({x:50,y:50});});

test("new elements select immediately, properties match selection, and wheel zoom changes canvas size",async({page})=>{await openImage(page);await expect(page.getByRole("group",{name:"Selected element properties"})).toHaveCount(0);const stage=page.getByTestId("advanced-workbench-stage");let b=(await stage.boundingBox())!;await page.mouse.move(b.x+25,b.y+25);await page.mouse.down();await page.mouse.move(b.x+140,b.y+110);await page.mouse.up();await expect(page.getByRole("button",{name:"rectangle tool",exact:true})).toHaveAttribute("aria-pressed","true");await expect(page.getByLabel("Element color")).toBeVisible();await page.getByLabel("Element color").fill("#12aa34");await page.getByLabel("Element size").fill("9");await page.getByRole("button",{name:"ellipse tool",exact:true}).click();await expect(page.getByRole("group",{name:"Selected element properties"})).toHaveCount(0);b=(await stage.boundingBox())!;await page.mouse.move(b.x+180,b.y+30);await page.mouse.down();await page.mouse.move(b.x+280,b.y+110);await page.mouse.up();await expect(page.getByLabel("Element color")).toHaveValue("#12aa34");await expect(page.getByLabel("Element size")).toHaveValue("9");await expect(page.getByRole("button",{name:"Merge annotations",exact:true})).toHaveCount(0);const before=(await stage.boundingBox())!.width;await stage.hover();await stage.dispatchEvent("wheel",{deltaY:-100,ctrlKey:true,bubbles:true,cancelable:true});await expect.poll(async()=>(await stage.boundingBox())!.width).toBeGreaterThan(before);});
test("closing newest Edit never selects an older open image",async({page})=>{await openImage(page);const png=await page.evaluate(()=>{const c=document.createElement("canvas");c.width=80;c.height=40;return c.toDataURL("image/png").split(",")[1];});await page.locator('input[type="file"]').setInputFiles({name:"Second.png",mimeType:"image/png",buffer:Buffer.from(png,"base64")});await expect(page.locator('.document-title')).toHaveText("Second.png");await page.evaluate(()=>(window as any).__EMIT__("fershot-editor-closed"));await expect(page.getByTestId("advanced-workbench-stage")).toHaveCount(0);await expect(page.getByRole("button",{name:"Image size",exact:true})).toBeDisabled();await expect(page.getByRole("button",{name:"Close image",exact:true})).toHaveCount(0);await expect(page.locator('[data-tauri-drag-region]')).toHaveCount(1);});
test("FTP preview authentication error supports explicit retry",async({page})=>{await mock(page);await page.context().addInitScript(()=>{(window as any).__MISSING_PREVIEW__=true;});await page.goto("/");await page.getByRole("option",{name:/frozen.png/}).click();await expect(page.getByRole("button",{name:"Retry preview",exact:true})).toBeVisible();await page.evaluate(()=>(window as any).__MISSING_PREVIEW__=false);await page.getByRole("button",{name:"Retry preview",exact:true}).click();await expect(page.getByRole("img",{name:"Shared.png",exact:true})).toBeVisible();});

test("ellipse and arrow previews follow their geometry before pointer release",async({page})=>{await openImage(page);const stage=page.getByTestId("advanced-workbench-stage");for(const tool of ["ellipse","arrow"]){await page.getByRole("button",{name:`${tool} tool`,exact:true}).click();const b=(await stage.boundingBox())!;await page.mouse.move(b.x+40,b.y+40);await page.mouse.down();await page.mouse.move(b.x+140,b.y+100);await page.waitForTimeout(40);const alpha=await stage.locator("canvas").last().evaluate((canvas:HTMLCanvasElement)=>{const ratio=canvas.width/canvas.getBoundingClientRect().width,ctx=canvas.getContext("2d")!;return {corner:ctx.getImageData(Math.round(140*ratio),Math.round(40*ratio),1,1).data[3],curve:ctx.getImageData(Math.round(90*ratio),Math.round(40*ratio),1,1).data[3]};});expect(alpha.corner).toBe(0);if(tool==="ellipse")expect(alpha.curve).toBeGreaterThan(0);await page.mouse.up();}});

test("image viewport stays 16:9 and does not move when element properties appear",async({page})=>{await openImage(page);const viewport=page.getByRole("region",{name:"Image workspace",exact:true}),stage=page.getByTestId("advanced-workbench-stage"),before=(await viewport.boundingBox())!,canvas=(await stage.boundingBox())!;expect(before.width/before.height).toBeCloseTo(16/9,2);await page.mouse.move(canvas.x+40,canvas.y+40);await page.mouse.down();await page.mouse.move(canvas.x+160,canvas.y+100);await page.mouse.up();await expect(page.getByLabel("Element size")).toBeVisible();const after=(await viewport.boundingBox())!,next=(await stage.boundingBox())!;expect(after).toEqual(before);expect(next).toEqual(canvas);await expect(page.getByRole("button",{name:/Prepare PNG|Drag prepared PNG/})).toHaveCount(0);await expect(page.locator('.editor-window-drag')).toContainText("FerShot X — Edit");});
test("side resize preserves stroke size and exports without rotation controls",async({page})=>{await openImage(page);const stage=page.getByTestId("advanced-workbench-stage");let b=(await stage.boundingBox())!;await page.mouse.move(b.x+40,b.y+40);await page.mouse.down();await page.mouse.move(b.x+160,b.y+100);await page.mouse.up();await page.getByLabel("Element size").fill("7");await page.getByRole("button",{name:"select tool",exact:true}).click();await page.mouse.click((await stage.boundingBox())!.x+40,(await stage.boundingBox())!.y+60);b=(await stage.boundingBox())!;await page.mouse.move(b.x+160,b.y+70);await page.mouse.down();await page.mouse.move(b.x+200,b.y+70);await page.mouse.up();await expect(page.getByLabel("Element size")).toHaveValue("7");await expect.poll(async()=>{const rows=await calls(page,"local_cache_save_draft");return rows.at(-1)?.args.request.draft.advanced[0]?.annotation.points[1].x;}).toBeCloseTo(200,0);await expect(page.getByLabel("Element rotation")).toHaveCount(0);await page.getByRole("button",{name:"Copy image",exact:true}).click();await expect.poll(()=>calls(page,"copy_image")).toHaveLength(1);const item=(await calls(page,"local_cache_save_draft")).at(-1).args.request.draft.advanced[0];expect(item.rotation??0).toBe(0);expect(item.annotation.style.strokeWidth).toBe(7);});
test("blur is a movable nondestructive element included in exported pixels",async({page})=>{await openImage(page);await page.getByRole("button",{name:"blur tool",exact:true}).click();const stage=page.getByTestId("advanced-workbench-stage"),b=(await stage.boundingBox())!;await page.mouse.move(b.x+20,b.y+20);await page.mouse.down();await page.mouse.move(b.x+100,b.y+100);await page.mouse.up();await page.getByRole("button",{name:"Copy image",exact:true}).click();await expect.poll(()=>calls(page,"copy_image")).toHaveLength(1);const png=(await calls(page,"copy_image"))[0].args.request.pngBase64;const red=await page.evaluate(async png=>{const image=new Image();image.src="data:image/png;base64,"+png;await image.decode();const c=document.createElement("canvas");c.width=image.width;c.height=image.height;const ctx=c.getContext("2d")!;ctx.drawImage(image,0,0);return ctx.getImageData(39,60,1,1).data[0];},png);expect(red).toBeLessThan(220);expect(await calls(page,"apply_image_effect")).toHaveLength(0);expect(await calls(page,"process_image")).toHaveLength(0);});
test("Library double-click opens Local in Edit and FTP in browser",async({page})=>{await mock(page);await page.goto("/");await page.getByRole("option",{name:/frozen.png/}).dblclick();await expect.poll(()=>calls(page,"ftp_open_in_browser")).toHaveLength(1);expect(await calls(page,"edit_library_image")).toHaveLength(0);await page.getByRole("tab",{name:/Local/}).click();await page.getByRole("option",{name:/Design.png/}).dblclick();await expect.poll(()=>calls(page,"edit_library_image")).toHaveLength(1);expect((await calls(page,"edit_library_image"))[0].args).toEqual({kind:"local",id:"local-1"});});


test("right status shows live color, Tab copies it, and percentage click fits the image",async({page})=>{await openImage(page);const stage=page.getByTestId("advanced-workbench-stage"),b=(await stage.boundingBox())!;await page.mouse.move(b.x+60,b.y+60);await expect(page.getByLabel("Pointer color",{exact:true})).toHaveText("#147EFB");await stage.focus();await page.keyboard.press("Tab");await expect.poll(()=>calls(page,"copy_text")).toHaveLength(1);expect((await calls(page,"copy_text"))[0].args.request.text).toBe("#147EFB");expect(await page.locator('.editor-status-strip').evaluate(el=>el.children.length)).toBe(3);const before=(await stage.boundingBox())!.width;await stage.hover();await stage.dispatchEvent("wheel",{deltaY:-120,ctrlKey:true,bubbles:true,cancelable:true});await expect.poll(async()=>(await stage.boundingBox())!.width).toBeGreaterThan(before);await page.getByRole("button",{name:"Fit image",exact:true}).click();await expect.poll(async()=>(await stage.boundingBox())!.width).toBeCloseTo(before,0);await expect(page.getByRole("button",{name:/^(Settings|Library|Close image|Print image|Crop|Resize)$/})).toHaveCount(0);});
test("small toolbar moves tools into More without resetting editor history",async({page})=>{await openImage(page);await drag(page,"advanced-workbench-stage");await expect(page.getByLabel("Advanced item count")).toHaveText("1 items");await page.setViewportSize({width:520,height:700});const more=page.getByLabel("More tools",{exact:true});await expect(more).toBeVisible();await expect(page.getByRole("button",{name:"arrow tool",exact:true})).toHaveCount(0);await more.click();await page.getByRole("button",{name:"arrow tool",exact:true}).click();await expect(page.locator('.editor-tool-overflow')).not.toHaveAttribute("open","");await expect(page.getByLabel("Advanced item count")).toHaveText("1 items");const widths=await page.locator('.editor-tool-slot>button').evaluateAll(nodes=>nodes.map(node=>Math.round(node.getBoundingClientRect().width)));expect(widths.every(width=>width===32)).toBe(true);});
test("Shift draws circular ellipses and axis-constrained arrows",async({page})=>{await openImage(page);await page.getByRole("button",{name:"ellipse tool",exact:true}).click();let b=(await page.getByTestId("advanced-workbench-stage").boundingBox())!;await page.keyboard.down("Shift");await page.mouse.move(b.x+30,b.y+30);await page.mouse.down();await page.mouse.move(b.x+160,b.y+80);await page.mouse.up();await page.keyboard.up("Shift");await expect.poll(async()=>{const rows=await calls(page,"local_cache_save_draft");return rows.at(-1)?.args.request.draft.advanced.length;}).toBe(1);let item=(await calls(page,"local_cache_save_draft")).at(-1).args.request.draft.advanced[0],a=item.annotation.points[0],z=item.annotation.points[1];expect(z.x-a.x).toBeCloseTo(z.y-a.y);await page.getByRole("button",{name:"arrow tool",exact:true}).click();b=(await page.getByTestId("advanced-workbench-stage").boundingBox())!;await page.keyboard.down("Shift");await page.mouse.move(b.x+100,b.y+30);await page.mouse.down();await page.mouse.move(b.x+230,b.y+50);await page.mouse.up();await page.keyboard.up("Shift");await expect.poll(async()=>{const rows=await calls(page,"local_cache_save_draft");return rows.at(-1)?.args.request.draft.advanced.length;}).toBe(2);item=(await calls(page,"local_cache_save_draft")).at(-1).args.request.draft.advanced[1];expect(item.annotation.points[1].y).toBeCloseTo(item.annotation.points[0].y);});

