test("effects expose relevant properties and magnifier keeps a circular resize policy",async({page})=>{await openImage(page,false);await page.getByRole("button",{name:"highlight tool",exact:true}).click();await drag(page,"advanced-workbench-stage");await expect(page.getByLabel("Selection manipulation")).toHaveText("Eight handles and center movement");await expect(page.getByLabel("Element size")).toHaveCount(0);await page.getByLabel("Highlight Opacity").fill("0.5");await page.getByRole("button",{name:"spotlight tool",exact:true}).click();await drag(page,"advanced-workbench-stage");await expect(page.getByLabel("Element color")).toHaveCount(0);await page.getByLabel("Dimming",{exact:true}).fill("0.8");await page.getByRole("button",{name:"blur tool",exact:true}).click();await drag(page,"advanced-workbench-stage");await expect(page.getByLabel("Element color")).toHaveCount(0);await page.getByLabel("Blur Strength").fill("12");await page.getByRole("button",{name:"magnifier tool",exact:true}).click();const b=(await page.getByTestId("advanced-workbench-stage").boundingBox())!;await page.mouse.move(b.x+140,b.y+100);await page.mouse.down();await page.mouse.move(b.x+180,b.y+100);await page.mouse.up();await expect(page.getByLabel("Selection manipulation")).toHaveText("Four corners; proportional resize and movement");await page.getByLabel("Magnification",{exact:true}).fill("3");await expect.poll(async()=>{const rows=await calls(page,"local_cache_save_draft");return rows.at(-1)?.args.request.draft.advanced.length;}).toBe(4);const items=(await calls(page,"local_cache_save_draft")).at(-1).args.request.draft.advanced;expect(items[0].effect.opacity).toBe(.5);expect(items[1].effect.dimOpacity).toBe(.8);expect(items[2].annotation.blurRadius).toBe(12);expect(items[3].effect.zoom).toBe(3);});

