test("sampled blur and magnifier contents hide during movement and resize, then resample on release",async({page})=>{
 for(const tool of ["blur","magnifier"]){
  await openImage(page,false);await page.getByRole("button",{name:`${tool} tool`,exact:true}).click();const stage=page.getByTestId("advanced-workbench-stage"),b=(await stage.boundingBox())!;
  await page.mouse.move(b.x+60,b.y+60);await page.mouse.down();await page.mouse.move(b.x+120,b.y+120);await page.mouse.up();await expect(page.getByLabel("Advanced item count"),tool).toHaveText("1 items");await page.getByRole("button",{name:"select tool",exact:true}).click();await expect(page.getByRole("button",{name:"select tool",exact:true})).toHaveAttribute("aria-pressed","true");
  await expect.poll(async()=>{const rows=await calls(page,"local_cache_save_draft");return rows.at(-1)?.args.request.draft.advanced[0]?.itemKind;}).toBe(tool==="blur"?"contract":"emphasis");const cx=tool==="blur"?90:120,cy=tool==="blur"?90:120;
  await page.mouse.click(b.x+cx,b.y+cy);await page.screenshot({path:`artifacts/qa/C80-${tool}-selection.png`});await expect(page.getByLabel("Selection manipulation"),tool).not.toHaveText("No selection");
  const alpha=async(x:number,y:number)=>stage.locator("canvas").nth(1).evaluate((c:HTMLCanvasElement,{x,y})=>{const ratio=c.width/c.getBoundingClientRect().width;return c.getContext("2d")!.getImageData(Math.round(x*ratio),Math.round(y*ratio),1,1).data[3];},{x,y});
  await page.mouse.move(b.x+cx,b.y+cy);await page.mouse.down();await page.mouse.move(b.x+cx+20,b.y+cy+10,{steps:5});await expect.poll(()=>alpha(cx+20,cy+10)).toBe(0);await page.mouse.up();await expect.poll(()=>alpha(cx+20,cy+10)).toBeGreaterThan(0);
  const radius=tool==="blur"?30:Math.hypot(60,60),right=cx+20+radius,top=cy+10-radius;
  await page.mouse.move(b.x+right,b.y+top);await page.mouse.down();await page.mouse.move(b.x+right+12,b.y+top-8,{steps:5});await expect.poll(()=>alpha(cx+20,cy+10)).toBe(0);await page.mouse.up();await expect.poll(()=>alpha(cx+20,cy+10)).toBeGreaterThan(0);
 }
});


