test("Library multi-select copies FTP links oldest first and confirms bulk remote deletion",async({page})=>{
 await mock(page);await page.addInitScript(()=>{const w=window as any;const now=Date.now();w.__FTP__=[0,1,2].map(i=>({id:`ftp-${i}`,sourceId:`source-${i}`,name:`Image${i}.png`,remotePath:`/s/image${i}.png`,url:`https://example.invalid/s/image${i}.png`,status:"success",createdAt:now-i*1000,updatedAt:now}));});await page.goto("/");
 const options=page.getByRole("option");await options.nth(0).click();await options.nth(2).click({modifiers:["Shift"]});await expect(page.getByRole("option",{selected:true})).toHaveCount(3);
 await page.getByRole("button",{name:"Copy links",exact:true}).click();await expect.poll(()=>calls(page,"copy_text")).toHaveLength(1);expect((await calls(page,"copy_text"))[0].args.request.text).toBe("https://example.invalid/s/image2.png\nhttps://example.invalid/s/image1.png\nhttps://example.invalid/s/image0.png");
 await page.getByRole("button",{name:"Delete selected from FTP",exact:true}).click();expect(await calls(page,"ftp_delete_remote")).toHaveLength(0);await page.getByRole("button",{name:"Cancel",exact:true}).click();expect(await calls(page,"ftp_delete_remote")).toHaveLength(0);
 await options.nth(1).click({modifiers:["Meta"]});await expect(page.getByRole("option",{selected:true})).toHaveCount(2);await page.getByRole("button",{name:"Delete selected from FTP",exact:true}).click();await page.getByRole("button",{name:"Delete permanently",exact:true}).click();await expect.poll(()=>calls(page,"ftp_delete_remote")).toHaveLength(2);expect((await calls(page,"ftp_delete_remote")).map((c:any)=>c.args.id)).toEqual(["ftp-0","ftp-2"]);
});

