test("tool hints appear immediately below controls and fixed shortcuts do not edit text fields",async({page})=>{
 await openImage(page,false);const rectangle=page.getByRole("button",{name:"rectangle tool",exact:true});await rectangle.hover();await expect(page.getByRole("tooltip")).toHaveText("Rectangle(R)");await expect(rectangle).not.toHaveAttribute("title");const control=(await rectangle.boundingBox())!,hint=(await page.getByRole("tooltip").boundingBox())!;expect(hint.y).toBeGreaterThan(control.y+control.height);
 await page.mouse.move(10,150);for(const [key,tool]of [["r","rectangle"],["b","blur"],["m","magnifier"],["v","select"],["t","text"]]){await page.keyboard.press(key);await expect(page.getByRole("button",{name:`${tool} tool`,exact:true})).toHaveAttribute("aria-pressed","true");}
 const b=(await page.getByTestId("advanced-workbench-stage").boundingBox())!;await page.mouse.click(b.x+60,b.y+60);await page.getByRole("textbox",{name:"Annotation text",exact:true}).fill("Rectangle b v m");await expect(page.getByRole("button",{name:"text tool",exact:true})).toHaveAttribute("aria-pressed","true");
});

test("Add Image inserts a movable image layer into the current draft and export",async({page})=>{
 await openImage(page);await drag(page,"advanced-workbench-stage");const add=page.getByRole("button",{name:"Add image",exact:true});await add.hover();await expect(page.getByRole("tooltip")).toHaveCount(0);await expect(add).not.toHaveAttribute("aria-keyshortcuts");
 await page.evaluate(()=>{const w=window as any,c=document.createElement("canvas");c.width=c.height=20;c.getContext("2d")!.fillStyle="#00ff00";c.getContext("2d")!.fillRect(0,0,20,20);w.__ADDED_PNG__=c.toDataURL("image/png").split(",")[1];w.__OPEN_FILE__=true;});
 await add.click();await expect(page.getByRole("menuitem",{name:"Clipboard",exact:true})).toHaveCount(0);await page.getByRole("menuitem",{name:"Open File",exact:true}).click();await expect(page.locator(".document-title")).toHaveText("Release.png");await expect(page.getByLabel("Advanced item count")).toHaveText("2 items");await expect(page.getByLabel("Selection manipulation")).toHaveText("Four corners; proportional resize and movement");
 await expect.poll(async()=>{const rows=await calls(page,"local_cache_save_draft");return rows.at(-1)?.args.request.draft.advanced[1]?.itemKind;}).toBe("image");const b=(await page.getByTestId("advanced-workbench-stage").boundingBox())!;
 await page.mouse.move(b.x+200,b.y+120);await page.mouse.down();await page.mouse.move(b.x+230,b.y+140,{steps:5});await page.mouse.up();await expect.poll(async()=>{const rows=await calls(page,"local_cache_save_draft");return rows.at(-1)?.args.request.draft.advanced[1]?.rect.x;}).toBeCloseTo(220,0);
 await page.mouse.move(b.x+240,b.y+150);await page.mouse.down();await page.mouse.move(b.x+260,b.y+170,{steps:5});await page.mouse.up();await expect.poll(async()=>{const rows=await calls(page,"local_cache_save_draft");return rows.at(-1)?.args.request.draft.advanced[1]?.rect.width;}).toBeGreaterThan(30);
 await page.getByRole("button",{name:"Copy image",exact:true}).click();await expect.poll(()=>calls(page,"copy_image")).toHaveLength(1);const png=(await calls(page,"copy_image"))[0].args.request.pngBase64;const pixel=await page.evaluate(async png=>{const image=new Image();image.src="data:image/png;base64,"+png;await image.decode();const c=document.createElement("canvas");c.width=image.width;c.height=image.height;c.getContext("2d")!.drawImage(image,0,0);return [...c.getContext("2d")!.getImageData(230,140,1,1).data];},png);expect(pixel).toEqual([0,255,0,255]);
 await page.getByRole("button",{name:"Undo",exact:true}).click();await page.getByRole("button",{name:"Undo",exact:true}).click();await page.getByRole("button",{name:"Undo",exact:true}).click();await expect(page.getByLabel("Advanced item count")).toHaveText("1 items");await page.getByRole("button",{name:"Redo",exact:true}).click();await expect(page.getByLabel("Advanced item count")).toHaveText("2 items");
 await expect.poll(async()=>{const rows=await calls(page,"local_cache_save_draft");return rows.at(-1)?.args.request.draft.advanced[1]?.itemKind;}).toBe("image");const saved=(await calls(page,"local_cache_save_draft")).at(-1).args.request;
 await page.evaluate(()=>(window as any).__EMIT__("fershot-editor-closed"));await expect(page.getByTestId("advanced-workbench-stage")).toHaveCount(0);await page.evaluate(id=>{const w=window as any;w.__INBOX__.push({...w.__DRAFTS__[id],localId:id});w.__EMIT__("fershot-editor-image");},saved.id);await expect(page.getByLabel("Advanced item count")).toHaveText("2 items");
});

test("Add Image cancellation preserves the document; capture inserts instead of replacing it",async({page})=>{
 await openImage(page);await drag(page,"advanced-workbench-stage");await page.getByRole("button",{name:"Add image",exact:true}).click();await page.getByRole("menuitem",{name:"Open File",exact:true}).click();await expect.poll(()=>calls(page,"open_image_dialog")).toHaveLength(1);await expect(page.getByLabel("Advanced item count")).toHaveText("1 items");await page.keyboard.press("Meta+o");expect(await calls(page,"open_image_dialog")).toHaveLength(1);
 await page.getByRole("button",{name:"Add image",exact:true}).click();await page.getByRole("menuitem",{name:"Capture Area",exact:true}).click();await expect.poll(()=>calls(page,"capture_image")).toHaveLength(1);await expect(page.getByLabel("Advanced item count")).toHaveText("2 items");await expect(page.locator(".document-title")).toHaveText("Release.png");
});

test("FTP progress refresh does not download the same preview again",async({page})=>{
 await mock(page);await page.goto("/");await page.getByRole("option").first().click();await expect(page.getByRole("img",{name:"Shared.png",exact:true})).toBeVisible();expect(await calls(page,"library_image")).toHaveLength(1);
 await page.evaluate(()=>{const w=window as any;w.__FTP__=w.__FTP__.map((item:any)=>({...item,updatedAt:Date.now()+1,status:"uploading"}));w.__EMIT__("fershot-ftp-updated");});await expect(page.getByRole("option").first()).toContainText("uploading");expect(await calls(page,"library_image")).toHaveLength(1);
});


test("Freehand only draws until Select enables moving and proportional resize",async({page})=>{
 await openImage(page,false);await page.getByRole("button",{name:"pen tool",exact:true}).click();const b=(await page.getByTestId("advanced-workbench-stage").boundingBox())!;await page.mouse.move(b.x+40,b.y+40);await page.mouse.down();await page.mouse.move(b.x+100,b.y+80,{steps:6});await page.mouse.move(b.x+180,b.y+50,{steps:6});await page.mouse.up();await expect(page.getByLabel("Advanced item count")).toHaveText("1 items");await expect(page.getByLabel("Element size",{exact:true})).toBeVisible();await page.getByLabel("Element size",{exact:true}).fill("6");await expect(page.getByLabel("Selection manipulation")).toHaveText("Drawing only; Select to move or resize");await page.mouse.click(b.x+350,b.y+200);await expect(page.getByRole("button",{name:"pen tool",exact:true})).toHaveAttribute("aria-pressed","true");await expect(page.getByLabel("Advanced item count")).toHaveText("1 items");
 await page.mouse.move(b.x+80,b.y+60);await page.mouse.down();await page.mouse.move(b.x+120,b.y+100,{steps:5});await page.mouse.up();await expect(page.getByLabel("Advanced item count")).toHaveText("2 items");
 await page.getByRole("button",{name:"select tool",exact:true}).click();await page.mouse.click(b.x+50,b.y+45);await expect(page.getByLabel("Selection manipulation")).toHaveText("Four corners; proportional resize and movement");await expect(page.getByLabel("Element size",{exact:true})).toHaveValue("6");
 await page.mouse.move(b.x+180,b.y+80);await page.mouse.down();await page.mouse.move(b.x+220,b.y+100,{steps:5});await page.mouse.up();await expect(page.getByLabel("Advanced item count")).toHaveText("2 items");await expect.poll(async()=>{const rows=await calls(page,"local_cache_save_draft");return rows.at(-1)?.args.request.draft.advanced[0]?.annotation.points.at(-1).x;}).toBeGreaterThan(180);

});

test("opening zoom is capped by the padded viewport while small images stay 100",async({page})=>{
 await openImage(page,false);await expect(page.getByLabel("Zoom percentage",{exact:true})).toHaveText("100%");const png=await page.evaluate(()=>{const c=document.createElement("canvas");c.width=1200;c.height=800;return c.toDataURL("image/png").split(",")[1];});await page.locator('input[type="file"]').setInputFiles({name:"Large.png",mimeType:"image/png",buffer:Buffer.from(png,"base64")});await expect(page.locator(".document-title")).toHaveText("Large.png");await expect.poll(async()=>parseInt(await page.getByLabel("Zoom percentage",{exact:true}).innerText())).toBeLessThanOrEqual(80);const frame=page.locator(".stage");expect(await frame.evaluate(el=>el.scrollWidth<=el.clientWidth+1&&el.scrollHeight<=el.clientHeight+1)).toBe(true);await page.getByRole("button",{name:"Fit image",exact:true}).click();
});


test("manual window shrinking keeps the full image visible without automatic scroll",async({page})=>{
 await openImage(page,false);await page.evaluate(()=>{Object.defineProperty(screen,"availWidth",{get:()=>1280});Object.defineProperty(screen,"availHeight",{get:()=>720});});await page.setViewportSize({width:480,height:380});await expect.poll(()=>page.locator(".stage").evaluate(el=>el.scrollWidth<=el.clientWidth+1&&el.scrollHeight<=el.clientHeight+1)).toBe(true);
});


test("opening wide and tall images uses the available viewport without blank-space scrolling",async({page})=>{
 await openImage(page,false);for(const [width,height]of [[1000,600],[240,1000],[2400,600],[400,240]]){const png=await page.evaluate(({width,height})=>{const c=document.createElement("canvas");c.width=width;c.height=height;return c.toDataURL("image/png").split(",")[1];},{width,height});await page.locator('input[type="file"]').setInputFiles({name:`Image-${width}-${height}.png`,mimeType:"image/png",buffer:Buffer.from(png,"base64")});await expect(page.locator(".document-title")).toHaveText(`Image-${width}-${height}.png`);await expect.poll(()=>page.locator(".stage").evaluate(el=>({x:el.scrollWidth-el.clientWidth,y:el.scrollHeight-el.clientHeight}))).toEqual({x:0,y:0});}
});


test("touchpad wheel scrolls without zoom and Safari pinch scales continuously",async({page})=>{
 await openImage(page,false);const stage=page.getByTestId("advanced-workbench-stage"),surface=page.locator(".editor-surface");const zoom=page.getByLabel("Zoom percentage",{exact:true});await stage.dispatchEvent("wheel",{deltaX:3,deltaY:7.5,bubbles:true,cancelable:true});await expect(zoom).toHaveText("100%");
 await surface.evaluate(node=>node.dispatchEvent(new Event("gesturestart",{bubbles:true,cancelable:true})));for(const scale of [1.5,3]){await surface.evaluate((node,scale)=>{const event=new Event("gesturechange",{bubbles:true,cancelable:true});Object.defineProperty(event,"scale",{value:scale});node.dispatchEvent(event);},scale);await expect(zoom).toHaveText(`${scale*100}%`);}await surface.evaluate(node=>node.dispatchEvent(new Event("gestureend",{bubbles:true})));
 await stage.dispatchEvent("wheel",{deltaMode:1,deltaY:3,bubbles:true,cancelable:true});await expect(zoom).not.toHaveText("300%");
});

test("Escape copies and hides Edit while editable text and crop Escape keep their context",async({page})=>{
 await openImage(page,false);await page.getByTestId("advanced-workbench-stage").focus();await page.keyboard.press("Escape");await expect.poll(()=>calls(page,"copy_image")).toHaveLength(1);await expect.poll(()=>calls(page,"hide_workspace")).toHaveLength(1);
 await page.getByRole("button",{name:"text tool",exact:true}).click();const b=(await page.getByTestId("advanced-workbench-stage").boundingBox())!;await page.mouse.click(b.x+50,b.y+50);await page.getByRole("textbox",{name:"Annotation text"}).focus();await page.keyboard.press("Meta+c");expect(await calls(page,"copy_image")).toHaveLength(1);
 await page.getByTestId("advanced-workbench-stage").focus();await page.keyboard.press("Meta+c");await expect.poll(()=>calls(page,"copy_image")).toHaveLength(2);await expect.poll(()=>calls(page,"hide_workspace")).toHaveLength(2);
});

test("scroll capture failures restore Edit and retain a technical diagnostic code",async({page})=>{
 await openImage(page,false);const shown=(await calls(page,"show_editor")).length;await page.evaluate(()=>{const w=window as any,invoke=w.__TAURI_INTERNALS__.invoke;w.__TAURI_INTERNALS__.invoke=async(command:string,args:any)=>{if(command==="capture_scroll_image"){w.__CALLS__.push({command,args});throw {code:"scroll_coordinates_missing",message:"Native selection coordinates are unavailable."};}return invoke(command,args);};w.__EMIT__("fershot-menu-action","capture-scrolling");});await expect(page.getByRole("alert").first()).toContainText("Native selection coordinates");await expect.poll(()=>calls(page,"show_editor")).toHaveLength(shown+1);await expect.poll(async()=>{const events=await calls(page,"record_diagnostic");return events.some((c:any)=>c.args.input.code==="scroll_coordinates_missing"&&c.args.input.operation==="capture_scroll_image"&&typeof c.args.input.durationMs==="number");}).toBe(true);
});

test("all window versions share spacing and UI labels cannot be selected like web text",async({page})=>{
 await mock(page);const metrics=[];for(const url of ["/?editor","/","/?preferences"]){await page.goto(url);const title=page.getByLabel("App version",{exact:true});await expect(title).toHaveText(`v${APP_VERSION}`);metrics.push(await title.evaluate(el=>{const rect=el.getBoundingClientRect(),parent=el.parentElement!.getBoundingClientRect(),style=getComputedStyle(el);return {right:parent.right-rect.right,height:rect.height,font:style.fontSize,weight:style.fontWeight};}));await expect(page.locator("body")).toHaveCSS("user-select","none");}expect(metrics[0]).toEqual(metrics[1]);expect(metrics[1]).toEqual(metrics[2]);
});


test("Escape aborts an active drawing gesture and failed Copy never hides Edit",async({page})=>{
 await openImage(page);const stage=page.getByTestId("advanced-workbench-stage"),b=(await stage.boundingBox())!;await page.mouse.move(b.x+30,b.y+30);await page.mouse.down();await page.mouse.move(b.x+130,b.y+90);await page.keyboard.press("Escape");await page.mouse.up();await expect(page.getByLabel("Advanced item count")).toHaveText("0 items");expect(await calls(page,"copy_image")).toHaveLength(0);
 await page.evaluate(()=>{const w=window as any,invoke=w.__TAURI_INTERNALS__.invoke;w.__TAURI_INTERNALS__.invoke=async(command:string,args:any)=>{if(command==="copy_image"){w.__CALLS__.push({command,args});throw {code:"clipboard_failed",message:"Synthetic clipboard failure"};}return invoke(command,args);};});await stage.focus();await page.keyboard.press("Escape");await expect(page.getByRole("alert").first()).toContainText("Synthetic clipboard failure");expect(await calls(page,"hide_workspace")).toHaveLength(0);
});

async function instantUploadMock(page:Page){await page.evaluate(()=>{const w=window as any,invoke=w.__TAURI_INTERNALS__.invoke;w.__AUTO_UPLOAD__=true;w.__TAURI_INTERNALS__.invoke=async(command:string,args:any)=>{if(command==="ftp_enqueue"){w.__CALLS__.push({command,args});if(w.__AUTO_ENQUEUE_FAIL__)throw {code:"ftp_credentials",message:"Save FTP settings first."};const item={id:`auto-${Date.now()}`,sourceId:args.request.sourceId,name:args.request.name,remotePath:"/s/auto.png",url:"https://example.invalid/s/auto.png",status:"pending",createdAt:Date.now(),updatedAt:Date.now()};w.__FTP__=[item];return item;}return invoke(command,args);};});}

test("instant capture queues and copies its URL without opening or replacing Edit",async({page})=>{
 await openImage(page,false);await instantUploadMock(page);const shown=(await calls(page,"show_editor")).length,sized=(await calls(page,"fit_editor_window")).length;
 await page.evaluate(()=>(window as any).__EMIT__("fershot-menu-action","capture-fullscreen"));await expect.poll(()=>calls(page,"ftp_start")).toHaveLength(1);await expect.poll(()=>calls(page,"copy_text")).toHaveLength(1);expect((await calls(page,"capture_image"))[0].args).toEqual({mode:"fullscreen",background:true});expect((await calls(page,"copy_text"))[0].args.request.text).toBe("https://example.invalid/s/auto.png");expect(await calls(page,"show_editor")).toHaveLength(shown);expect(await calls(page,"fit_editor_window")).toHaveLength(sized);await expect(page.locator(".document-title")).toHaveText("Release.png");
 await page.evaluate(()=>{const w=window as any;w.__FTP__=w.__FTP__.map((item:any)=>({...item,status:"success",updatedAt:Date.now()+1}));w.__EMIT__("fershot-ftp-updated");});await expect.poll(()=>calls(page,"local_cache_remove")).toHaveLength(1);expect(await calls(page,"show_editor")).toHaveLength(shown);
});

test("asynchronous instant-upload failure restores the captured image for recovery",async({page})=>{
 await openImage(page,false);await instantUploadMock(page);const shown=(await calls(page,"show_editor")).length;await page.evaluate(()=>(window as any).__EMIT__("fershot-menu-action","capture-area"));await expect.poll(()=>calls(page,"ftp_start")).toHaveLength(1);
 await page.evaluate(()=>{const w=window as any;w.__FTP__=w.__FTP__.map((item:any)=>({...item,status:"failed",error:"Synthetic transfer failure",updatedAt:Date.now()+1}));w.__EMIT__("fershot-ftp-updated");});await expect(page.getByRole("alert").first()).toContainText("Automatic FTP upload failed");await expect.poll(async()=>(await calls(page,"show_editor")).length).toBeGreaterThan(shown);await expect(page.locator(".document-title")).toContainText("Capture-");expect(await calls(page,"ftp_enqueue")).toHaveLength(1);
});

test("instant enqueue failure preserves pixels and opens Edit; switching off returns normal capture",async({page})=>{
 await openImage(page,false);await instantUploadMock(page);await page.evaluate(()=>{const w=window as any;w.__AUTO_ENQUEUE_FAIL__=true;w.__EMIT__("fershot-menu-action","capture-window");});await expect(page.getByRole("alert").first()).toContainText("Save FTP settings first");await expect(page.locator(".document-title")).toContainText("Capture-");expect(await calls(page,"ftp_start")).toHaveLength(0);
 await page.evaluate(()=>{const w=window as any;w.__AUTO_UPLOAD__=false;w.__EMIT__("fershot-menu-action","capture-fullscreen");});await expect.poll(()=>calls(page,"capture_image")).toHaveLength(2);expect((await calls(page,"capture_image"))[1].args).toEqual({mode:"fullscreen"});expect(await calls(page,"ftp_enqueue")).toHaveLength(1);
});


test("new capture is painted before Edit is shown and discarded backing pixels repaint on focus",async({page})=>{
 await openImage(page,false);
 await expect.poll(()=>calls(page,"show_editor")).toHaveLength(1);
 await page.evaluate(()=>{
  const w=window as any,invoke=w.__TAURI_INTERNALS__.invoke;
  const c=document.createElement("canvas");c.width=80;c.height=60;c.getContext("2d")!.fillStyle="#12b834";c.getContext("2d")!.fillRect(0,0,80,60);
  const pngBase64=c.toDataURL("image/png").split(",")[1];w.__PRESENTED__=[];
  w.__TAURI_INTERNALS__.invoke=async(command:string,args:any)=>{
   if(command==="capture_image"){w.__CALLS__.push({command,args});return {width:80,height:60,pngBase64,byteSize:atob(pngBase64).length};}
   if(command==="fit_editor_window"){w.__CALLS__.push({command,args});await new Promise<void>(resolve=>{w.__RELEASE_SIZE__=resolve;});return;}
   if(command==="show_editor"){const canvas=document.querySelector(".konvajs-content canvas")as HTMLCanvasElement;w.__PRESENTED__.push(Array.from(canvas.getContext("2d")!.getImageData(4,4,1,1).data));}
   return invoke(command,args);
  };
  w.__EMIT__("fershot-menu-action","capture-area");
 });
 await expect(page.locator(".document-title")).toContainText("Capture-");
 expect(await calls(page,"show_editor")).toHaveLength(1);
 await page.evaluate(()=>(window as any).__RELEASE_SIZE__());
 await expect.poll(()=>page.evaluate(()=>(window as any).__PRESENTED__)).toEqual([[18,184,52,255]]);
 await page.locator(".konvajs-content canvas").first().evaluate((canvas:HTMLCanvasElement)=>canvas.getContext("2d")!.clearRect(0,0,canvas.width,canvas.height));
 await page.evaluate(()=>window.dispatchEvent(new Event("focus")));
 await expect.poll(()=>page.locator(".konvajs-content canvas").first().evaluate((canvas:HTMLCanvasElement)=>Array.from(canvas.getContext("2d")!.getImageData(4,4,1,1).data))).toEqual([18,184,52,255]);
});
